// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address actor, address recipient) public {
        vm.assume(actor != address(0));
        vm.assume(recipient != address(0));
        vm.assume(actor != recipient);
        vm.deal(address(c), 1 ether);
        vm.prank(actor);
        bool ok;
        try c.withdrawAll(recipient) { ok = true; } catch { ok = false; }
        bool expectedOk = (actor == address(this));
        assertTrue(ok == expectedOk);
    }
}
